// TAKMA - Katalog produktów Zebra Technologies
// Dane zebrane z oficjalnych źródeł Zebra

export interface Product {
  id: string
  slug: string
  name: string
  shortDescription: string
  description: string
  categoryId: string
  subcategoryIds?: string[]
  manufacturerId: string
  priceFrom?: number
  images: string[]
  imageDescriptions?: string[]
  tags: ProductTag[]
  availability: 'available' | 'on-order' | 'unavailable'
  isNew: boolean
  isBestseller: boolean
  keyParams?: {
    rodzajDruku: string
    rozdzielczosc: string
    predkoscDruku: string
    szerokoscDruku: string
    szerokoscEtykiet: string
  }
  specifications: ProductSpecification[]
  applications: string[]
  variants?: ProductVariant[]
  compatibleAccessories: string[]
  compatibleFoilLabels?: string[]
  relatedAccessories?: string[]
  faq?: { question: string; answer: string }[]
  comparison?: {
    title: string
    models: { name: string; slug?: string; highlight?: boolean; specs: Record<string, string> }[]
  }
  gtin13?: string
  editorialReview?: {
    ratingValue: number
    bestRating: number
    reviewBody: string
  }
  variantAttributeTooltips?: Record<string, string>
  downloads: ProductDownload[]
  servicePlans?: ServicePlan[]
  createdAt: string
  updatedAt?: string
  sameAs?: string
}

export interface ProductVariant {
  partNumber: string
  name: string
  attributes: Record<string, string>
  priceFrom?: number
  availability: 'available' | 'on-order' | 'unavailable'
}

export interface ProductSpecification {
  name: string
  value: string
}

export interface ProductDownload {
  name: string
  type: 'pdf' | 'datasheet' | 'manual' | 'software'
  url: string
  size: string
}

export interface ServicePlan {
  name: string
  partNumber: string
  duration: string
  priceNetto: number
}

export type ProductTag = 'magazyn' | 'retail' | 'produkcja' | 'logistyka' | 'healthcare' | 'outdoor'

export interface Category {
  id: string
  slug: string
  name: string
  description: string
  seoTitle: string
  seoDescription: string
  longDescription: string
  icon: string
  productCount: number
}

export interface Subcategory {
  id: string
  slug: string
  name: string
  parentCategoryId: string
  parentSubcategoryId?: string
  description: string
  seoTitle: string
  seoDescription: string
  longDescription: string
  icon: string
  productIds: string[]
  productCount: number
}

export interface Manufacturer {
  id: string
  slug: string
  name: string
  logo: string
  seoTitle?: string
  seoDescription?: string
}

