// Tabela porównawcza serii etykiet — helper z highlight
function makeLabelComparison(highlightSeries: string) {
  const allModels = [
    {
      name: 'Z-Perform 1000T',
      specs: {
        'Typ papieru': 'Niepowlekany (matowy)',
        'Klej': 'Trwały akrylowy',
        'Temp. aplikacji': 'od +5°C',
        'Temp. użytkowania': '-18°C do +93°C',
        'Zalecana taśma': 'Zebra 2300 Wax',
        'Zastosowania': 'Magazyn, logistyka, produkcja',
        'Jakość nadruku': 'Standard',
        'Cena': 'Ekonomiczna',
      },
    },
    {
      name: 'Z-Select 2000T',
      specs: {
        'Typ papieru': 'Powlekany (top-coated)',
        'Klej': 'Trwały akrylowy',
        'Temp. aplikacji': 'od +5°C',
        'Temp. użytkowania': '-18°C do +93°C',
        'Zalecana taśma': 'Zebra 3200 Wax/Resin',
        'Zastosowania': 'Produkty, farmacja, retail',
        'Jakość nadruku': 'Premium',
        'Cena': 'Premium',
      },
    },
    {
      name: '8000T All-Temp',
      specs: {
        'Typ papieru': 'Niepowlekany + klej mrozoodporny',
        'Klej': 'Trwały mrozoodporny',
        'Temp. aplikacji': 'od -29°C',
        'Temp. użytkowania': '-54°C do +93°C',
        'Zalecana taśma': 'Zebra 3200 Wax/Resin',
        'Zastosowania': 'Chłodnie, mroźnie, cold chain',
        'Jakość nadruku': 'Standard',
        'Cena': 'Premium',
      },
    },
  ]
  return {
    title: 'Porównanie serii etykiet termotransferowych Zebra fi76',
    models: allModels.map(m => ({
      ...m,
      highlight: m.name === highlightSeries,
    })),
  }
}

