const foilLabels76: Product[] = foilLabel76Specs.map(s => {
  const seriesSlugMap: Record<string, string> = {
    'Z-Ultimate 3000T': 'z-ultimate-3000t',
    'Z-Ultimate 3000T Silver': 'z-ultimate-3000t-silver',
    'Z-Ultimate 3100T Gloss': 'z-ultimate-3100t-gloss',
    '8000T Void Matte Silver': '8000t-void-matte-silver',
  }
  const serSlug = seriesSlugMap[s.series]
  const dimStr = `${String(s.w).replace('.', ',')} × ${String(s.h).replace('.', ',')} mm`
  const dimSlug = `${String(s.w).replace('.', '-')}x${String(s.h).replace('.', '-')}`
  const isSilver = s.series.includes('Silver') && !s.series.includes('Void')
  const isGloss = s.series.includes('Gloss')
  const isVoid = s.series.includes('Void')

  const descBody = isVoid
    ? 'Etykiety zabezpieczające (tamper-evident) — po oderwaniu pozostawiają widoczny napis VOID na powierzchni. Srebrna matowa folia poliestrowa. Do zabezpieczania sprzętu, gwarancji i dokumentacji.'
    : isGloss
      ? 'Z-Ultimate 3100T Gloss to błyszczące etykiety poliestrowe o najwyższej jakości nadruku — doskonała ostrość kodów kreskowych i grafik. Odporne na ścieranie, chemikalia i UV.'
      : isSilver
        ? 'Srebrne etykiety foliowe na podłożu poliestrowym — profesjonalny wygląd i najwyższa trwałość. Idealne do tabliczek znamionowych, oznaczeń sprzętu i etykiet bezpieczeństwa.'
        : 'Etykiety foliowe Z-Ultimate 3000T na podłożu poliestrowym zapewniają najwyższą trwałość — odporność na ścieranie, wilgoć, chemikalia, rozpuszczalniki i temperatury od -40°C do +150°C.'

  return {
    id: `zebra-foil76-${s.pn.toLowerCase()}`,
    slug: `zebra-etykiety-foliowe-${serSlug}-${dimSlug}${s.dupSlug ? `-${s.qty}` : ''}-fi76`,
    name: `Etykiety foliowe Zebra ${s.series} ${dimStr} (${s.qty} szt.) fi76`,
    shortDescription: `Etykiety foliowe termotransferowe ${isSilver ? 'srebrne ' : isGloss ? 'błyszczące ' : isVoid ? 'zabezpieczające ' : ''}${dimStr}, fi76, ${s.qty} szt. na rolce`,
    description: `Oryginalne etykiety foliowe termotransferowe Zebra ${s.series} o wymiarach ${dimStr} na gilzę fi76 mm. Rolka zawiera ${s.qty} sztuk etykiet.\n\n${descBody}\n\nKompatybilne z drukarkami przemysłowymi Zebra: ZT111, ZT231, ZT411, ZT421, ZT510, ZT610, ZT620. Wymagają taśmy żywicznej (resin) Zebra 5095 lub 5100.`,
    categoryId: 'materialy-eksploatacyjne',
    subcategoryIds: ['etykiety-termotransferowe-foliowe'],
    manufacturerId: 'zebra',
    priceFrom: s.price,
    images: [] as string[],
    tags: (isVoid ? ['produkcja', 'retail', 'logistyka'] : ['magazyn', 'produkcja', 'logistyka']) as ProductTag[],
    availability: 'available' as const,
    isNew: false,
    isBestseller: false,
    specifications: [
      { name: 'Part Number', value: s.pn },
      { name: 'Seria', value: s.series },
      { name: 'Typ druku', value: 'Termotransferowy (thermal transfer)' },
      { name: 'Wymiar etykiety', value: dimStr },
      { name: 'Ilość na rolce', value: `${s.qty} szt.` },
      { name: 'Nawój (gilza)', value: 'fi76 mm' },
    ],
    applications: isVoid
      ? ['Etykiety zabezpieczające', 'Plomby gwarancyjne', 'Zabezpieczenia sprzętu elektronicznego']
      : isSilver
        ? ['Tabliczki znamionowe', 'Oznaczenia sprzętu', 'Etykiety bezpieczeństwa']
        : isGloss
          ? ['Etykiety premium', 'Oznaczenia produktów', 'Etykiety z grafiką']
          : ['Tabliczki znamionowe', 'Oznaczenia sprzętu przemysłowego', 'Etykiety odporne na chemikalia'],
    compatibleAccessories: [] as string[],
    downloads: [
      { name: 'Karta katalogowa Z-Ultimate 3000T (EN)', type: 'datasheet' as const, url: 'https://www.zebra.com/content/dam/zebra_dam/en/spec-sheets/supplies/labels-tags/z-ultimate-3000t-spec-sheet-en-us.pdf', size: 'PDF' },
    ],
    faq: foilLabel76Faq,
    editorialReview: {
      ratingValue: isVoid ? 4.8 : isGloss ? 4.9 : 4.8,
      bestRating: 5,
      reviewBody: isVoid
        ? `Etykiety zabezpieczające Zebra ${s.series} ${dimStr} fi76 — niezawodna ochrona przed manipulacją z efektem VOID.`
        : isGloss
          ? `Etykiety foliowe Zebra ${s.series} ${dimStr} fi76 — błyszcząca powierzchnia premium z najwyższą jakością nadruku.`
          : isSilver
            ? `Etykiety foliowe Zebra ${s.series} ${dimStr} fi76 — profesjonalne srebrne etykiety do tabliczek znamionowych.`
            : `Etykiety foliowe Zebra ${s.series} ${dimStr} fi76 — najwyższa trwałość do zastosowań przemysłowych.`,
    },
    createdAt: '2025-01-01',
  } as Product
})

